export const deleteVisaPostingSummaryItem = (file) => (dispath) => {
	axios
		.delete(`${BASE_URL}/admin/logs/delete?filename=${file.filename}`)
		.then((response) => {
			dispath({
				type    : DELETE_VISA_POSTING_SUMMARY_ITEM,
				payload : { data: file.id },
			});
		})
		.catch((error) => {
			dispath({
				type    : DELETE_VISA_POSTING_SUMMARY_ITEM_ERROR,
				payload : error,
			});
		});
};

