export const downloadInterAffReportGross = (date, region, issuerCode) => async (dispatch) => {
	dispatch({
		type    : DOWNLOADING_STATUS,
		payload : { data: true },
	});
	try {
		if (region === "Region" || issuerCode === "Issuer")
			throw new Error("Error! Please select a region and issuer code to download");
		const response = await axios({
			method       : "GET",
			headers      : { Accept: "application/octet-stream" },
			url          : `${BASE_URL}/inter-affiliate/v2/reports/gross-settlement?settlementDate=${date}&region-code=${region}&issuer-code=${issuerCode}`,
			responseType : "blob", // important
		});
		const url = window.URL.createObjectURL(new Blob([ response.data ]));
		const link = document.createElement("a");
		link.href = url;
		link.setAttribute("download", date + ` InterAffiliate_Gross_Report_For_${region}_Region.txt`);
		document.body.appendChild(link);
		link.click();
		dispatch({
			type    : DOWNLOADING_STATUS,
			payload : { data: false },
		});
	} catch (error) {
		let data = true;
		if (error.message) data = error.message;
		dispatch({
			type    : DOWNLOADING_STATUS,
			payload : { data: false },
		});
		dispatch({
			type    : OPEN_ALERT,
			payload : { data },
		});
	}
};

