// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { useParams, useHistory, Redirect, useLocation } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";
import moment from "moment";
import Pagination2 from "react-js-pagination";

// Redux
import { connect } from "react-redux";
import { fetchInterPostingLog, downloadInterPostingLog } from "../../../actions/filesets";
import { closeAlert } from "../../../actions/utils";

// Components
import { Alert, Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import PostingTableHeader from "../../../components/PostingTableHeader";
import PostingTable from "../../../components/PostingTable";
import ErrorMessage from "../../../components/ErrorMessage";

// query string
const queryString = require("query-string");

const GenericPostingRecords = ({
	// function props
	fetchInterPostingLog,
	downloadInterPostingLog,
	closeAlert,
	// query string props
	location                   : { search: queryParams, state: prevUrl }, // gets the query string from props.search and save it as queryParams
	// state variables props
	alertError,
	genericPostingRecords,
	genericPostingRecordsError,
}) => {
	// QUERY STRING VARIABLES
	const LogID = queryString.parse(queryParams)["posting-log-id"];
	const affiliateCode = queryString.parse(queryParams).affiliateCode;
	let { page } = queryString.parse(queryParams);

	// constants
	const Location = useLocation();
	const backUrl = Location.state && Location.state.backUrl;

	useEffect(() => {
		localStorage.setItem("prevUrl", backUrl);
	}, []);

	const { settlementDate } = useParams();
	let dateOnDownloadedFileName = moment(settlementDate).format("DDMMYY");
	const tokenInlocalStrage = localStorage.getItem("token");

	// initialize
	const history = useHistory();

	// Use Effect Handles General Updates
	useEffect(
		() => {
			const pageQuery = page - 1;
			fetchInterPostingLog(LogID, affiliateCode, pageQuery);
		},
		[ LogID ],
	);

	const [ activePage, setActivePage ] = useState(parseInt(page));
	useEffect(
		() => {
			// handles page change via url
			setActivePage(parseInt(page));
		},
		[ page ],
	);

	useEffect(
		() => {
			const pageQuery = page - 1;
			fetchInterPostingLog(LogID, affiliateCode, pageQuery);
		},
		[ queryParams ],
	);

	const onDismiss = () => {
		closeAlert();
	};

	const handlePageChange = (pageNumber) => {
		history.push(
			`/admin/${settlementDate}/query-posting-records?posting-log-id=${LogID}&affiliateCode=${affiliateCode}&page=${pageNumber}`,
		);
		setActivePage(pageNumber);
	};

	const handleGoBack = (prevLocation) => {
		if (prevLocation) history.push(`${prevLocation}`);
		return;
		// history.goBack(); // fallback incase some unlikely things happens.
	};

	const GenericPostingRecordTable = [
		"Branch",
		"Home Branch",
		"Constant",
		"Constant1",
		"Fcy Amount",
		"GL Account No",
		"Dr Cr",
		"GL Account Branch",
		"Fcy Currency",
		"Lcy Amount",
		"Tx Code",
		"Date",
		"Rate",
		"Constant2",
		"Narration",
		"Summary Order",
	];

	if (!tokenInlocalStrage) return <Redirect to={"/"} />;

	return (
		<div className='animated fadeIn'>
			{alertError && (
				<Alert color='danger' toggle={onDismiss}>
					{alertError ? alertError : "Error unable to download. Please Check you entries!"}
				</Alert>
			)}
			<Row>
				<Col lg={2}>
					<Button
						color={"primary"}
						size={"sm"}
						className={"btn-block my-2 mx-2"}
						onClick={() => handleGoBack(localStorage.getItem("prevUrl"))}
					>
						Go Back
					</Button>
				</Col>
			</Row>
			<Row>
				<Col lg={12}>
					<Card className={"mx-2"}>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<FormattedMessage id=' Admin Posting Log' defaultMessage=' Admin Posting Log' />
							</strong>
							<Button
								className={"btn-sm mx-1 px-4 py-1"}
								onClick={() => downloadInterPostingLog(LogID, dateOnDownloadedFileName, affiliateCode)}
								color='success'
							>
								{" "}
								<FormattedMessage id='Download' defaultMessage='Download' />
							</Button>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!genericPostingRecordsError &&
							!genericPostingRecords && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle Errors */}
							{!genericPostingRecords &&
							genericPostingRecordsError &&
							genericPostingRecordsError.data === "" && (
								<ErrorMessage message={"Error unable to display entries!"} />
							)}

							{/* Handle 404 */}
							{!genericPostingRecordsError &&
							genericPostingRecords &&
							genericPostingRecords.data &&
							genericPostingRecords.data.content.length === 0 && (
								<ErrorMessage message={"There are no posting log entries for this item  "} />
							)}

							{/* Handle display content */}
							{genericPostingRecords &&
							genericPostingRecords.data &&
							genericPostingRecords.data.content.length > 0 && (
								<Table2 hover bordered striped responsive size='sm' style={{ minWidth: "180%" }}>
									<thead>
										<PostingTableHeader
											headerType={"array"}
											headerPayload={GenericPostingRecordTable}
										/>
									</thead>
									<tbody>
										<PostingTable
											tableName={"generic-posting-record"}
											dataRecords={
												genericPostingRecords && genericPostingRecords.data ? (
													genericPostingRecords.data.content
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table2>
							)}

							{/* Handle Pagination */}
							{genericPostingRecords &&
							genericPostingRecords.data &&
							genericPostingRecords.data &&
							genericPostingRecords.data.content.length > 0 && (
								<nav>
									<Pagination2
										activePage={activePage}
										itemsCountPerPage={genericPostingRecords.data.size}
										totalItemsCount={
											(genericPostingRecords && genericPostingRecords.data.totalElements) || null
										}
										pageRangeDisplayed={20}
										onChange={handlePageChange}
									/>
								</nav>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		alertError                 : state.utils.alertError,
		genericPostingRecords      : state.fileSets.genericPostingRecords,
		genericPostingRecordsError : state.fileSets.genericPostingRecordsError,
	};
};

export default connect(mapStateToProps, {
	fetchInterPostingLog,
	downloadInterPostingLog,
	closeAlert,
})(GenericPostingRecords);
