// Styles
import "./App.css";
// CoreUI Icons Set
import "@coreui/icons/css/coreui-icons.min.css";
// Import Flag Icons Set
import "flag-icon-css/css/flag-icon.min.css";
// Import Font Awesome Icons Set
import "font-awesome/css/font-awesome.min.css";
// Import Simple Line Icons Set
import "simple-line-icons/css/simple-line-icons.css";
// Import Main styles for this application
import "./scss/style.css";

// Bootstrap Js
import "bootstrap/dist/js/bootstrap.js";

// React
import React, { useEffect } from "react";
import { Route, Switch, Redirect, withRouter } from "react-router-dom";
import { setLocale } from "./actions/locale";
import { IntlProvider } from "react-intl";
import locale_en from "react-intl/locale-data/en";
import locale_de from "react-intl/locale-data/de";
import locale_fr from "react-intl/locale-data/fr";
import locale_pt from "react-intl/locale-data/pt";
import locale_es from "react-intl/locale-data/es";

import { addLocaleData } from "react-intl";
import messages_de from "./translations/de.json";
import messages_en from "./translations/en.json";
import messages_fr from "./translations/fr.json";
import messages_pt from "./translations/pt.json";
import messages_es from "./translations/es.json";

// Redux
import { connect } from "react-redux";
import { getUserMgtUrl, getUserMgtUrlBackEnd } from "./actions/utils";

// Containers
import { DefaultLayout } from "./containers";
// Pages
import { Login, Page404, Page500, Register } from "./views/Pages";

// components
import ErrorBoundary from "./components/ErrorBoundary";
import GenericPostingRecords from "./views/Schemes/GenericPostingRecords/GenericPostingRecords";

// util
import getToken from "./Utils/getToken";

const messages = {
	de : messages_de,
	en : messages_en,
	fr : messages_fr,
	pt : messages_pt,
	es : messages_es,
};
addLocaleData([ ...locale_en, ...locale_de, ...locale_fr, ...locale_pt, ...locale_es ]);

const Token = getToken(window.location.search);

// Standared react-router Private route for performing authentication check on protected routes.
const PrivateRoute = ({ component: Component, ...rest }) => (
	<Route
		{...rest}
		render={(props) => (Token ? <Component {...props} /> : <Redirect to={{ pathname: "/login" }} />)}
	/>
);

const App = ({
	// destructure the action creators first.
	getUserMgtUrlBackEnd,
	getUserMgtUrl,
	setLocale,
	// destructure the props from reducer
	lang,
}) => {
	useEffect(() => {
		getUserMgtUrl();
		getUserMgtUrlBackEnd();
	}, []);

	if (localStorage.se8lementLang) setLocale(localStorage.se8lementLang);
	return (
		<IntlProvider locale={lang} messages={messages[lang]}>
			<Switch>
				<Route
					exact
					path='/admin/:settlementDate/query-posting-records'
					name='Generic Posting Records'
					component={GenericPostingRecords}
				/>
				<Route exact path='/login' name='Login Page' component={Login} />
				<Route exact path='/register' name='Register Page' component={Register} />
				<Route exact path='/404' name='Page 404' component={Page404} />
				<Route exact path='/500' name='Page 500' component={Page500} />
				<ErrorBoundary>
					<PrivateRoute path='/' name='Home' component={DefaultLayout} />
				</ErrorBoundary>
			</Switch>
		</IntlProvider>
	);
};

const mapStateToProps = (state) => {
	return { lang: state.locale.lang };
};

export default withRouter(
	connect(mapStateToProps, {
		setLocale,
		getUserMgtUrl,
		getUserMgtUrlBackEnd,
	})(App),
);
