import moment from "moment";
export const todaysDateFunc = () => {
	// defaults the date param for fx-history route to today's date dynamically
	// console.log(moment(this.state.startDate).format());
	let date1 = moment().format();
	if (date1.includes("T")) {
		let extract = date1.split("T");
		date1 = extract[0];
		return date1;
	}
};
