export const openAlert = () => (dispatch) => {
	dispatch({
		type    : OPEN_ALERT,
		payload : { data: true },
	});
};

export const closeAlert = () => (dispatch) => {
	dispatch({
		type    : CLOSE_ALERT,
		payload : { data: false },
	});
};

