export const approveAuthorization = (id, name) => (dispatch) => {
	axios
		.put(`${BASE_URL}/${name.toLowerCase()}?redisKey=${id}`, {})
		.then((response) => {
			response.data.redisId = id;
			dispatch({
				type    : APPROVE_AUTHORIZATION,
				payload : response,
			});
		})
		.catch((err) => {
			dispatch({
				type    : APPROVE_AUTHORIZATION_ERROR,
				payload : err.response.data,
			});
		});
};
