import React, { useState, useEffect } from "react";
import { NavLink, useHistory } from "react-router-dom";
import PropTypes from "prop-types";

// Redux
import { connect } from "react-redux";
import { getLoggedInUser, fetchUserAffiliates, fetchUsers } from "../../actions/utils";
import { dispatchSelectedUserAffiliateCode } from "../../actions/filesets";

// components
import { UncontrolledDropdown, Badge, DropdownItem, DropdownMenu, DropdownToggle, Nav, NavItem } from "reactstrap";
import { AppHeaderDropdown, AppNavbarBrand, AppSidebarToggler } from "@coreui/react";
import activedge_logo from "../../assets/img/brand/settlement_logo.png";

const propTypes = {
	children : PropTypes.node,
};

const defaultProps = {};

const DefaultHeader = ({
	attributes,
	children,
	// action creators
	getLoggedInUser,
	fetchUserAffiliates,
	dispatchSelectedUserAffiliateCode,
	fetchUsers,
	// state props
	isUnAuthorized,
	userDetail,
	userAffiliates,
}) => {
	// instantiate history
	const history = useHistory();

	const [ account, setAccount ] = useState("");
	const [ selectedAffiliate, setSelectedAffiliate ] = useState("");

	useEffect(() => {
		(async () => {
			setSelectedAffiliate(localStorage.getItem("selectedAffilliate"));
			const data = await getLoggedInUser();
			localStorage.setItem("currentSelectedUserEmail", data.login);
			fetchUserAffiliates(data.login);
			fetchUsers();
		})();
	}, []);

	const [ allUserAffiliates, setAllUserAffiliates ] = useState([]);
	useEffect(
		() => {
			let selectedAffilliateFromLocalStorage = localStorage.getItem("selectedAffilliate");
			let arrayOfAffiliates = userAffiliates && userAffiliates.map((data) => data.code);
			let defaultAffiliate = arrayOfAffiliates && arrayOfAffiliates[0];
			setAllUserAffiliates(userAffiliates);
			localStorage.setItem("userAffilliates", JSON.stringify(allUserAffiliates));
			if (!selectedAffilliateFromLocalStorage || selectedAffilliateFromLocalStorage !== undefined)
				handleSelectAffiliate({ code: defaultAffiliate });
		},
		[ userAffiliates ],
	);

	useEffect(
		() => {
			if (localStorage.decodedToken) {
				setAccount(JSON.parse(localStorage.getItem("decodedToken")).sub);
			}
		},
		[ userDetail ],
	);

	const logOut = () => {
		localStorage.clear();
		history.push("/login");
		window.location.reload();
	};

	const handleSelectAffiliate = (affiliate) => {
		setSelectedAffiliate(affiliate.code);
		localStorage.setItem("selectedAffilliate", affiliate.code);
		dispatchSelectedUserAffiliateCode(affiliate.code);
	};

	const goToSettings = () => {
		history.push(`/settings`);
	};

	// const { children, ...attributes } = props;

	if (isUnAuthorized) {
		logOut();
	}

	return (
		<React.Fragment>
			<AppSidebarToggler className='d-lg-none' display='md' mobile />
			<AppNavbarBrand
				full={{ src: activedge_logo, width: 89, height: 25, alt: "ActivEdge Logo" }} // 70 width original
				minimized={{ src: activedge_logo, width: 30, height: 30, alt: "ActivEdge Logo" }}
			/>
			<AppSidebarToggler className='d-md-down-none' display='lg' />

			<Nav className='ml-auto' navbar>
				<NavItem className='d-md-down-none px-4'>
					<NavLink to='' className='nav-link'>
						<i className='icon-bell' />
						<Badge pill color='danger'>
							0
						</Badge>
					</NavLink>
				</NavItem>

				<UncontrolledDropdown direction='down'>
					<DropdownToggle nav>
						{selectedAffiliate ? (
							<span to=''>
								{" "}
								<i
									className={"flag-icon flag-icon-" + selectedAffiliate.toLowerCase() || ""}
									title='al'
									id='al'
								/>{" "}
								<strong>{selectedAffiliate}</strong>{" "}
								<i className='fa fa-caret-down' aria-hidden='true' />
							</span>
						) : (
							"N/A"
						)}
					</DropdownToggle>
					<DropdownMenu right>
						{allUserAffiliates &&
							allUserAffiliates.map((item, indx) => (
								<DropdownItem key={indx} onClick={() => handleSelectAffiliate(item)}>
									{item.name}
								</DropdownItem>
							))}
					</DropdownMenu>
				</UncontrolledDropdown>
				<AppHeaderDropdown direction='down'>
					<DropdownToggle nav>
						<img src={"assets/img/avatars/7.jpg"} className='img-avatar' alt='admin@bootstrapmaster.com' />
					</DropdownToggle>
					<DropdownMenu right>
						<DropdownItem header tag='div' className='text-center'>
							<strong>Account</strong>
						</DropdownItem>
						<DropdownItem>
							<i className='fa fa-user-o' /> {account}
						</DropdownItem>
						<DropdownItem onClick={goToSettings}>
							<i className='fa fa-cog' /> Settings
						</DropdownItem>
						<DropdownItem onClick={logOut}>
							<i className='fa fa-lock' /> Logout
						</DropdownItem>
					</DropdownMenu>
				</AppHeaderDropdown>
			</Nav>
			{/* <AppAsideToggler className="d-md-down-none" /> */}
			{/*<AppAsideToggler className="d-lg-none" mobile />*/}
		</React.Fragment>
	);
};

DefaultHeader.propTypes = propTypes;
DefaultHeader.defaultProps = defaultProps;

const mapStateToProps = (state) => {
	return {
		userAffiliates : state.utils.userAffiliates,
		userDetail     : state.utils.userDetail,
		isUnAuthorized : state.utils.isUnAuthorized,
	};
};

export default connect(mapStateToProps, {
	getLoggedInUser,
	fetchUserAffiliates,
	dispatchSelectedUserAffiliateCode,
	fetchUsers,
})(DefaultHeader);
